INSERT INTO entity_periods (entity_id,period_id,confidence,rationale,source_id,review_status)
INSERT INTO _r VALUES
 ('ENT_MAN_MANDA_D_HAYYI','emanates_from','ENT_MAN_HAYYI_RABBI','high','In Mandaean theology Manda d-Hayyi (''Knowledge of Life''), the chief revealer-savior, proceeds from Hayyi Rabbi (the Great Life); the Ginza Rba and Drower''s account present him as the messenger emanated by the supreme Life. Source: SRC_GINZA_RBA; SRC_DROWER_MANDAEANS.'),
 ('ENT_MAN_UTHRAS','emanates_from','ENT_MAN_HAYYI_RABBI','high','The uthras (lightworld beings) collectively emanate from the Great Life Hayyi Rabbi, source of the World of Light''s luminous beings. Source: SRC_GINZA_RBA; SRC_DROWER_MANDAEANS.'),
 ('ENT_MAN_MANA_RABBA','emanates_from','ENT_MAN_HAYYI_RABBI','medium','Mana Rabba (''Great Mind/Treasure''), the supreme principle/first being, is treated in Mandaean cosmogony as proceeding from or co-extensive with the Great Life Hayyi Rabbi at the head of the World of Light. Source: SRC_GINZA_RBA; SRC_DROWER_MANDAEANS.'),
 ('ENT_MAN_MANDA_D_HAYYI','member_of','ENT_MAN_UTHRAS','high','Manda d-Hayyi is the foremost of the uthras, the lightworld emissaries; he leads the rescuing uthras sent to the lower world. Source: SRC_MANDAEAN_BOOK_JOHN; SRC_DROWER_MANDAEANS.'),
 ('ENT_MAN_HIBIL_ZIWA','member_of','ENT_MAN_UTHRAS','high','Hibil Ziwa (Abel of Radiance), the lightworld savior who descends to the underworld, is one of the great uthras. Source: SRC_GINZA_RBA; SRC_DROWER_MANDAEANS.'),
 ('ENT_MAN_SITIL','member_of','ENT_MAN_UTHRAS','high','Sitil (Seth), brother in the Hibil-Sitil-Anosh triad of lightworld beings, is counted among the uthras. Source: SRC_GINZA_RBA; SRC_DROWER_MANDAEANS.'),
 ('ENT_MAN_ANOSH','member_of','ENT_MAN_UTHRAS','high','Anosh (Enosh), brother in the Hibil-Sitil-Anosh triad, is one of the lightworld uthras. Source: SRC_GINZA_RBA; SRC_DROWER_MANDAEANS.'),
 ('ENT_MAN_HIBIL_ZIWA','sibling_of','ENT_MAN_SITIL','high','Hibil, Sitil and Anosh form the classic Mandaean fraternal triad of saving lightworld figures (corresponding to Abel, Seth and Enosh). Source: SRC_GINZA_RBA; SRC_DROWER_MANDAEANS.'),
 ('ENT_MAN_SITIL','sibling_of','ENT_MAN_ANOSH','high','Sitil and Anosh are paired as brothers with Hibil in the lightworld triad. Source: SRC_GINZA_RBA; SRC_DROWER_MANDAEANS.'),
 ('ENT_MAN_HIBIL_ZIWA','sibling_of','ENT_MAN_ANOSH','high','Hibil and Anosh belong to the same fraternal triad of saving uthras. Source: SRC_GINZA_RBA; SRC_DROWER_MANDAEANS.'),
 ('ENT_MAN_ABATHUR','parent_of','ENT_MAN_PTAHIL','high','Abathur the weigher of souls fathers Ptahil the world-maker, whom he sends down to create the material cosmos. Source: SRC_GINZA_RBA; SRC_DROWER_MANDAEANS.'),
 ('ENT_MAN_PTAHIL','creator_of','ENT_MAN_TIBIL','high','Ptahil is the demiurge who shapes Tibil, the material earth/world, in the defective lower creation. Source: SRC_GINZA_RBA; SRC_DROWER_MANDAEANS.'),
 ('ENT_MAN_ABATHUR','judges','ENT_MAN_MATARTAS','medium','Abathur Muzania (''the weigher'') presides over the scales judging souls as they ascend through the matartas (purgatorial watch-stations). Source: SRC_GINZA_RBA; SRC_DROWER_MANDAEANS.'),
 ('ENT_MAN_ABATHUR','member_of','ENT_MAN_UTHRAS','medium','Abathur is a lightworld/uthra figure positioned at the boundary of the worlds of light and darkness, weighing souls. Source: SRC_DROWER_MANDAEANS.'),
 ('ENT_MAN_RUHA','parent_of','ENT_MAN_UR','high','Ruha bears Ur, the dragon-like ruler of the underworld, in Mandaean cosmogony. Source: SRC_GINZA_RBA; SRC_DROWER_MANDAEANS.'),
 ('ENT_MAN_RUHA','parent_of','ENT_MAN_PLANETS','high','Ruha is mother of the Seven (planets); together with Ur she generates the seven planetary rulers who govern the material world. Source: SRC_GINZA_RBA; SRC_DROWER_MANDAEANS.'),
 ('ENT_MAN_RUHA','parent_of','ENT_MAN_TWELVE','medium','Ruha is also reckoned mother/mistress of the Twelve (zodiacal/astral rulers) alongside the Seven planets in the lower world''s astral hierarchy. Source: SRC_GINZA_RBA; SRC_DROWER_MANDAEANS.'),
 ('ENT_MAN_RUHA','rules','ENT_MAN_WORLD_DARKNESS','high','Ruha is the dominant spirit governing the World of Darkness / lower world together with her offspring. Source: SRC_GINZA_RBA; SRC_DROWER_MANDAEANS.'),
 ('ENT_MAN_PLANETS','member_of','ENT_MAN_WORLD_DARKNESS','medium','The Seven planets belong to the dark, material lower order ruled by Ruha and Ur, opposed to the World of Light. Source: SRC_GINZA_RBA; SRC_DROWER_MANDAEANS.'),
 ('ENT_MAN_TWELVE','member_of','ENT_MAN_WORLD_DARKNESS','medium','The Twelve (zodiac/astral powers) form part of the lower astral order associated with the World of Darkness. Source: SRC_GINZA_RBA; SRC_DROWER_MANDAEANS.'),
 ('ENT_MAN_UR','dwells_in','ENT_MAN_WORLD_DARKNESS','high','Ur the underworld monster dwells in and embodies the World of Darkness. Source: SRC_GINZA_RBA; SRC_DROWER_MANDAEANS.'),
 ('ENT_MAN_WORLD_LIGHT','opposes','ENT_MAN_WORLD_DARKNESS','high','Mandaean cosmology is dualistic: the World of Light (Hayyi Rabbi and the uthras) stands opposed to the World of Darkness (Ruha, Ur, the planets and Twelve). Source: SRC_GINZA_RBA; SRC_DROWER_MANDAEANS.'),
 ('ENT_MAN_HAYYI_RABBI','rules','ENT_MAN_WORLD_LIGHT','high','Hayyi Rabbi, the Great Life, is the supreme being presiding over the World of Light. Source: SRC_GINZA_RBA; SRC_DROWER_MANDAEANS.'),
 ('ENT_MAN_UTHRAS','dwells_in','ENT_MAN_WORLD_LIGHT','high','The uthras inhabit the World of Light as its luminous denizens. Source: SRC_GINZA_RBA; SRC_DROWER_MANDAEANS.'),
 ('ENT_MAN_PTAHIL','member_of','ENT_MAN_UTHRAS','low','Ptahil originates as a lightworld uthra (son of Abathur) before his flawed demiurgic creation of the material world; he is an ambivalent uthra-demiurge. Source: SRC_GINZA_RBA; SRC_DROWER_MANDAEANS.'),
 ('ENT_MAN_HIBIL_ZIWA','opposes','ENT_MAN_UR','medium','Hibil Ziwa descends into the World of Darkness to subdue Ur and the powers of darkness, the central combat of Mandaean salvation history. Source: SRC_GINZA_RBA; SRC_DROWER_MANDAEANS.'),
 ('ENT_MAN_JOHN_BAPTIST','reception_of','ENT_SAINT_JOHN_BAPTIST','medium','The Mandaean Yahia Yuhana (John the Baptist), supreme prophet-teacher of the Mandaeans and central figure of the Mandaean Book of John, is a distinct religious reception of the historical John the Baptist (ENT_SAINT_JOHN_BAPTIST), cast as the true prophet of Jordan baptism and polemically against Jesus, contrasting the Christian reception. Intentional homonym (both flagged intentional_distinct in entity_duplicate_review); parallels ENT_ISL_YAHYA reception_of ENT_SAINT_JOHN_BAPTIST. Source: SRC_MANDAEAN_BOOK_JOHN; SRC_DROWER_MANDAEANS.'),
 ('ENT_MAN_JOHN_BAPTIST','member_of','ENT_MAN_UTHRAS','low','In Mandaean tradition John the Baptist is revered as a teacher guided by uthras and associated with the lightworld emissaries; modeled as affiliated with the uthra hierarchy. Source: SRC_MANDAEAN_BOOK_JOHN; SRC_DROWER_MANDAEANS.');
